use std::path::Path;

use unicodex_core::{ObjectStore, Value};

use super::{
    field_mut, mutate_report, put_value, remove_field, report_value, ACCEPTED, CHECKED, COMPLETED,
    FAILED, REJECTED,
};

pub(crate) fn with_schema(store: &ObjectStore, value: &Value, schema: &str) -> String {
    let Value::Map(mut root) = value.clone() else {
        unreachable!()
    };
    *field_mut(&mut root, "schema") = Value::Text(schema.to_owned());
    put_value(store, Value::Map(root))
}

pub(crate) fn legacy_v1(store: &ObjectStore, value: &Value) -> String {
    let cid = mutate_report(store, value, |acceptance| {
        for name in ["required", CHECKED, ACCEPTED, REJECTED, COMPLETED, FAILED] {
            remove_field(acceptance, name);
        }
    });
    with_schema(
        store,
        &report_value(store, &cid),
        "unicodex.stage_verification_report.v1",
    )
}

pub(crate) fn assert_prior_versions(cwd: &Path, store: &ObjectStore, value: &Value) -> String {
    for schema in [
        "unicodex.stage_verification_report.v5",
        "unicodex.stage_verification_report.v2",
    ] {
        super::super::assert_verified(cwd, &with_schema(store, value, schema), true);
    }
    let legacy = legacy_v1(store, value);
    super::super::assert_verified(cwd, &legacy, false);
    legacy
}

